python3 - <<'PY'
import json, os, re, subprocess

def run(*args):
    return subprocess.run(args, capture_output=True, text=True).stdout.strip()

root = run('git', 'rev-parse', '--show-toplevel') or '.'
branch = run('git', '-C', root, 'branch', '--show-current') or '(detached)'
role = 'worktree' if os.path.isfile(os.path.join(root, '.git')) else '主目录'
dirty = bool(run('git', '-C', root, 'status', '--short'))
state = 'dirty' if dirty else 'clean'

lines = [f'位置: {role}；分支: {branch}；工作区: {state}。']
if role == '主目录':
    if branch != 'main':
        lines.append('主目录应保持在本地 main；如需承载改动，请切到 worktree。')
    if dirty:
        lines.append('主目录应保持 clean，不要在主目录承载实现性改动。')

porcelain = run('git', '-C', root, 'worktree', 'list', '--porcelain')
paths = []
for block in porcelain.split('\n\n'):
    if not block.strip():
        continue
    first = block.splitlines()[0]
    if first.startswith('worktree '):
        paths.append(first.split(' ', 1)[1].strip())
linked = [p for p in paths if p != root]
dirty_worktrees = 0
for path in linked:
    if run('git', '-C', path, 'status', '--short'):
        dirty_worktrees += 1
if linked:
    lines.append(f'当前共有 {len(linked)} 个 linked worktree，其中 {dirty_worktrees} 个仍有本地改动；请在集成完成后及时回收。')

settings_local = os.path.join(root, '.claude', 'settings.local.json')
if os.path.exists(settings_local):
    try:
        text = open(settings_local, 'r', encoding='utf-8').read()
        refs = set(re.findall(r'\.claude/worktrees/([^/\s]+)', text))
        existing = {os.path.basename(p.rstrip('/')) for p in linked}
        stale = sorted(name for name in refs if name not in existing)
        if stale:
            lines.append(f'本地 settings.local.json 仍引用 {len(stale)} 个不存在的 worktree 路径，建议清理历史授权。')
    except OSError:
        pass

lines.append('开始新一轮任务前，请先确认最近成果已回到本地 main。')
print(json.dumps({'systemMessage': ' '.join(lines)}, ensure_ascii=False))
PY
